- t1: mutex_lock {"resource": "m1::a"}; mutex_lock {"resource": "m2::b"}; mutex_unlock {"resource": "m2::b"}; mutex_unlock {"resource": "m1::a"}; return {}
- main: scope {"funcs": ["m1::t1", "m2::t2"]}; return {}
module m2:
- t2: mutex_lock {"resource": "m1::a"}; mutex_lock {"resource": "m2::b"}; mutex_unlock {"resource": "m2::b"}; mutex_unlock {"resource": "m1::a"}; return {}

