// runtime can observe the protected values while both locks are held.

// Task t1 runs in module m1 and depends on m2::b (owned by module m2).
fn t1(a: &Arc<Mutex<i32>>, b: &Arc<Mutex<i32>>) {
    // Lock m1::a (owned by this module)
    let mut guard_a = a.lock().unwrap();
    // Lock m2::b (owned by the other module) while holding m1::a
    let mut guard_b = b.lock().unwrap();
    // Work while holding both resources at the same time:
    // update the observable protected values under both locks.
    *guard_a += 1;
    *guard_b += 1;
    // Release m2::b
    drop(guard_b);
    // Release m1::a
    drop(guard_a);
}

// Task t2 runs in module m2 and depends on m1::a (owned by module m1).
fn t2(a: &Arc<Mutex<i32>>, b: &Arc<Mutex<i32>>) {
    // Lock m1::a (owned by the other module)
    let mut guard_a = a.lock().unwrap();
    // Lock m2::b (owned by this module) while holding m1::a
    let mut guard_b = b.lock().unwrap();
    // Work while holding both resources at the same time:
    // update the observable protected values under both locks.
    *guard_a += 1;
    *guard_b += 1;
    // Release m2::b
    drop(guard_b);
    // Release m1::a
    drop(guard_a);
}

// Entry scope (m1::main): launches both tasks and finishes only after both finish.
fn main() {
    // Shared resources: a owned by module m1, b owned by module m2.
    let a = Arc::new(Mutex::new(0));
    let b = Arc::new(Mutex::new(0));

    let a_for_t1 = Arc::clone(&a);
    let b_for_t1 = Arc::clone(&b);
    let handle_t1 = thread::spawn(move || t1(&a_for_t1, &b_for_t1));

    let a_for_t2 = Arc::clone(&a);
    let b_for_t2 = Arc::clone(&b);
    let handle_t2 = thread::spawn(move || t2(&a_for_t2, &b_for_t2));

    // Join every spawned thread: main finishes only after both tasks finish.
    handle_t1.join().unwrap();
    handle_t2.join().unwrap();

    // After joins, main reads shared state only to print the terminal line.
    let done_a = *a.lock().unwrap();
    let done_b = *b.lock().unwrap();
    let done = if done_a > 0 && done_b > 0 { 1 } else { 0 };
    println!("DONE done={}", done);
}
